/** Render authored profile UI; identity and class values are escaped by the host. */
export function renderProfileView({profile, authUser, classes, signedIn, confirming = false, accountHeading, avatarArt, button, field, formError, submit, esc, t}) {
  if (!signedIn) return `<section class="portal-panel"><h1 id="portal-title" tabindex="-1">${t('Profil Saya')}</h1><p>${t('Anda sedang menggunakan mod tetamu. Log masuk untuk melihat dan menyimpan profil akaun anda.')}</p>${button(t('Log masuk'), 'profile-login', {primary: true})}</section>`;
  const user = authUser?.id === profile.id ? authUser : null;
  const email = typeof user?.email === 'string' && user.email ? user.email : profile.email;
  const phone = typeof user?.phone === 'string' ? user.phone.trim() : '';
  const legacy = typeof email === 'string' && email.endsWith('@accounts.geodecoder.invalid');
  const hasEmail = typeof email === 'string' && Boolean(email.trim()) && !legacy;
  const emailVerified = user && email === user.email ? Boolean(user.email_confirmed_at) : profile.email_verified;
  const choices = [['initial', 'Inisial'], ['cube', 'Kubus'], ['cuboid', 'Kuboid'], ['pyramid', 'Piramid'], ['cylinder', 'Silinder'], ['cone', 'Kon']];
  return `${accountHeading(t('AKAUN ANDA'), t('Profil Saya'), t('Pilih rupa anda. Nama dan avatar ini digunakan dalam akaun GeoDecoder.'))}
    <div class="portal-utility-navigation">${button(t('Kembali ke kelas'), 'profile-back', {quiet: true, symbol: 'home'})}${button(t('Tetapan Penggunaan'), 'profile-settings', {quiet: true})}${button(t('Kata Laluan & Keselamatan'), 'security', {quiet: true, symbol: 'lock'})}</div>
    ${confirming ? `<section class="portal-panel portal-profile-confirm" role="group" aria-labelledby="profile-unsaved-title"><h2 id="profile-unsaved-title">${t('Perubahan belum disimpan')}</h2><p>${t('Simpan nama dan avatar sebelum keluar, atau buang perubahan ini.')}</p><div class="dialog-actions">${button(t('Teruskan menyunting'), 'profile-stay', {quiet: true})}${button(t('Buang perubahan'), 'profile-discard', {danger: true})}${button(t('Simpan dan teruskan'), 'profile-save-leave', {primary: true})}</div></section>` : ''}
    <div class="portal-profile-layout"><section class="portal-panel"><h2>${t('Nama & avatar')}</h2><form data-portal-form="profile" novalidate>
      ${field('portal-profile-name', t('Nama paparan'), {name: 'display_name', autocomplete: 'nickname', value: profile.display_name, help: t('Gunakan 2–60 aksara. Nama pengguna anda kekal sama.')})}
      <div class="portal-profile-preview" data-profile-preview><span class="portal-avatar" data-profile-preview-avatar>${avatarArt(profile.avatar)}</span><span><small data-profile-preview-state>${t('Pratonton nama dan avatar')}</small><b data-profile-preview-name>${esc(profile.display_name)}</b></span></div>
      <fieldset class="portal-avatar-options"><legend>${t('Pilih avatar')}</legend>${choices.map(([id, label]) => `<label><input id="portal-avatar-${id}" type="radio" name="avatar" value="${id}" ${id === (profile.avatar || 'initial') ? 'checked' : ''} required><span class="portal-avatar">${avatarArt(id)}</span><span>${t(label)}</span></label>`).join('')}</fieldset>${formError()}${submit(t('Simpan'))}
    </form></section><section class="portal-panel portal-profile-details"><h2>${t('Maklumat akaun')}</h2><p class="portal-muted">${t('Maklumat ini baca sahaja. Peranan ditetapkan oleh sistem akaun.')}</p><dl>
      <dt>${t('Nama pengguna')}</dt><dd>@${esc(profile.username)}</dd><dt>${t('E-mel')}</dt><dd>${hasEmail ? esc(email) : t(legacy || !phone && authUser === undefined ? 'Tiada e-mel berdaftar (akaun lama).' : 'Tiada e-mel berdaftar.')}</dd>
      <dt>${t('Status pengesahan e-mel')}</dt><dd>${!hasEmail ? t('Tidak berkenaan') : emailVerified === true ? t('Disahkan') : emailVerified === false ? t('Belum disahkan') : t('Belum tersedia')}</dd>
      ${phone ? `<dt>${t('Nombor telefon')}</dt><dd>${esc(/^\d+$/.test(phone) ? '+' + phone : phone)}</dd><dt>${t('Status pengesahan telefon')}</dt><dd>${t(user.phone_confirmed_at ? 'Disahkan' : 'Belum disahkan')}<p class="portal-muted">${t('Gunakan nombor ini untuk menerima kod SMS semasa log masuk.')}</p></dd>` : ''}
      <dt>${t('Peranan')}</dt><dd>${t(profile.role === 'teacher' ? 'Guru' : profile.role === 'student' ? 'Murid' : 'Belum tersedia')}</dd>
      <dt>${t('Kelas')}</dt><dd>${classes.length ? `<ul class="portal-profile-classes">${classes.map(c => `<li><b>${esc(c.name)}</b><span>${t('Guru')}: ${c.teacher_name ? esc(c.teacher_name) : c.teacher_id === profile.id && profile.role === 'teacher' ? esc(profile.display_name) : t('Maklumat guru belum tersedia')}</span>${button(t('Buka kelas'), 'profile-class', {id: c.id, quiet: true})}</li>`).join('')}</ul>` : `${t('Belum ada kelas.')}${profile.role === 'student' ? `<p>${t('Gunakan PIN daripada guru untuk menyertai kelas.')}</p>${button(t('Sertai kelas'), 'profile-join', {primary: true})}` : button(t('Buka ruang kelas'), 'profile-back', {quiet: true})}`}</dd>
    </dl></section></div>`;
}
